<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { api } from '../../services/api';
import CharactersView from '../../views/CharactersView.vue';
import ScenesView from '../../views/ScenesView.vue';
import SvgIcon from '../SvgIcon.vue';
const props = defineProps({ projectId: String, state: Object });
const emit = defineEmits(['refresh', 'error']);
const STYLE_OPTIONS = [
  { value: 'Chinese 2.5D Donghua', label: '2.5D 国漫', hint: '立体细腻，电影感光影' },
  { value: 'Chinese 2D Anime', label: '2D 国漫', hint: '手绘线稿，赛璐璐上色' },
  { value: 'Cinematic Fantasy Animation', label: '电影感幻想动画', hint: '厚重氛围，戏剧性照明' },
  { value: 'Modern Manhua Flat Color', label: '现代平涂漫画', hint: '清晰轮廓，平涂色块' },
  { value: 'Chinese Ink Wash', label: '东方水墨', hint: '水墨笔触，矿物色彩' },
];
const tab = ref('characters'); const checking = ref(false); const extracting = ref(false); const generating = ref(false); const quality = ref(null); const notice = ref(''); const propsList = ref([]); const jobs = ref([]); const busyId = ref('');
const project = ref(null); const visualStyle = ref('Chinese 2.5D Donghua'); const savingStyle = ref(false);
let timer = null;
const deferredBackgrounds = computed(() => props.state?.content?.last_extraction?.deferred_backgrounds || []);
const activeStyle = computed(() => STYLE_OPTIONS.find(s => s.value === visualStyle.value) || STYLE_OPTIONS[0]);
async function loadProps() { try { const [propData, jobData] = await Promise.all([api.listProps(props.projectId), api.listJobs(props.projectId)]); propsList.value = propData; jobs.value = jobData.filter(j => j.target_type === 'prop'); } catch {} }
function jobFor(id) { return jobs.value.find(j => j.target_id === id && ['pending', 'running'].includes(j.status)); }
async function saveStyle() { savingStyle.value = true; try { project.value = await api.updateProject(props.projectId, { visual_style: visualStyle.value }); notice.value = `项目视觉风格已统一为「${activeStyle.value.label}」，之后新建的角色、场景、道具和分镜图片都会使用它。`; } catch(e) { emit('error', e.message); } finally { savingStyle.value = false; } }
async function check() { checking.value = true; try { quality.value = await api.reviewStage(props.projectId, 5); } catch(e) { emit('error', e.message); } finally { checking.value = false; } }
async function extract() { extracting.value = true; notice.value = ''; try { const result = await api.extractAssetsFromScripts(props.projectId); const created = result.content.last_extraction.created; const deferred = result.content.last_extraction.deferred_backgrounds?.length || 0; notice.value = `新增 ${created.characters} 个角色、${created.scenes} 个核心场景、${created.props} 个关键道具；${deferred} 类临时背景留给分镜生成。已有档案未覆盖。`; emit('refresh'); } catch(e) { emit('error', e.message); } finally { extracting.value = false; } }
async function generateMissing() { generating.value = true; try { const result = await api.generateMissingAssets(props.projectId); notice.value = result.message; await loadProps(); } catch(e) { emit('error', e.message); } finally { generating.value = false; } }
async function addProp() { try { await api.createProp(props.projectId, { name: '新道具', description: '', narrative_significance: '', visual_prompt: '' }); tab.value = 'props'; await loadProps(); } catch(e) { emit('error', e.message); } }
async function updateProp(prop) { try { await api.updateProp(prop.id, { name: prop.name, description: prop.description, narrative_significance: prop.narrative_significance, visual_prompt: prop.visual_prompt }); } catch(e) { emit('error', e.message); } }
async function removeProp(prop) { if (!window.confirm(`删除道具「${prop.name}」？已生成图片仍保留在资产库。`)) return; await api.deleteProp(prop.id); await loadProps(); }
async function generateProp(prop) { busyId.value = prop.id; try { await api.generateProp(prop.id); notice.value = `「${prop.name}」已按项目风格加入图片生成队列。`; await loadProps(); } catch(e) { emit('error', e.message); } finally { busyId.value = ''; } }
async function cancelJob(job) { busyId.value = job.id; try { await api.cancelJob(job.id); notice.value = `已停止「${job.target_name || '图片'}」生成任务。`; await loadProps(); } catch(e) { emit('error', e.message); } finally { busyId.value = ''; } }
async function save() { return await api.saveStage(props.projectId, 5, { ...props.state.content }); }
onMounted(async () => { loadProps(); try { project.value = await api.listProjects().then(rows => rows.find(p => p.id === props.projectId)); if (project.value) visualStyle.value = project.value.visual_style; } catch {} timer = setInterval(loadProps, 2500); });
onBeforeUnmount(() => clearInterval(timer));
defineExpose({ save });
</script>

<template>
  <div class="assets-stage">
    <section class="style-panel">
      <div class="style-copy"><span class="section-label">PROJECT LOOK</span><strong>项目统一视觉风格</strong><p>所有角色、场景、道具与分镜共用同一风格。修改只影响之后新生成的图片，不会覆盖已有参考图。</p></div>
      <div class="style-control"><label><span>当前风格</span><select v-model="visualStyle" @change="saveStyle" :disabled="savingStyle"><option v-for="style in STYLE_OPTIONS" :key="style.value" :value="style.value">{{ style.label }}</option></select></label><span>{{ savingStyle ? '正在保存…' : activeStyle.hint }}</span></div>
    </section>
    <div class="script-assets-actions"><div><strong>只建立需要统一的关键资产</strong><span>AI 会保留主要角色、核心场景和关键道具；一次性背景直接写入分镜画面，不额外生成参考图。</span></div><div><button class="btn secondary" :disabled="extracting || generating" @click="extract"><SvgIcon name="spark" :size="16" />{{ extracting ? '正在分析重要度…' : '从已审批剧本提取资产' }}</button><button class="btn primary" :disabled="generating || extracting" @click="generateMissing"><SvgIcon name="image" :size="16" />{{ generating ? '正在加入队列…' : '生成关键资产缺失图片' }}</button></div></div>
    <div v-if="notice" class="notice-strip">{{ notice }}<button @click="notice = ''">×</button></div>
    <section v-if="deferredBackgrounds.length" class="deferred-panel"><div><strong>留给分镜的临时背景</strong><span>无需独立参考图，生成对应分镜时直接描述即可。</span></div><div class="deferred-list"><span v-for="item in deferredBackgrounds" :key="item.name" :title="item.reason">{{ item.name }}</span></div></section>
    <div class="assets-toolbar"><div class="segmented"><button :class="{ active: tab === 'characters' }" @click="tab = 'characters'">角色资产</button><button :class="{ active: tab === 'scenes' }" @click="tab = 'scenes'">核心场景</button><button :class="{ active: tab === 'props' }" @click="tab = 'props'">关键道具</button></div><button class="btn secondary small" :disabled="checking" @click="check"><SvgIcon name="spark" :size="15" />{{ checking ? '检查中…' : '资产完整性检查' }}</button></div>
    <div v-if="quality" class="quality-strip" :class="{ good: !quality.issues.length }"><strong>{{ quality.summary }}</strong><span v-for="(issue, i) in quality.issues" :key="i">{{ issue.issue }} · {{ issue.suggestion }}</span><button @click="quality = null">×</button></div>
    <div class="embedded-assets"><CharactersView v-if="tab === 'characters'" :project-id="projectId" /><ScenesView v-else-if="tab === 'scenes'" :project-id="projectId" /><section v-else class="props-panel"><div class="props-heading"><div><h2>关键道具</h2><p>只保留影响剧情、反复出现或具有独特外观的物件。</p></div><button class="btn secondary small" @click="addProp"><SvgIcon name="plus" :size="15" />添加道具</button></div><p v-if="!propsList.length" class="muted">还没有道具。可从已审批剧本提取，也可以手动添加。</p><div class="prop-grid"><article v-for="prop in propsList" :key="prop.id" class="prop-card"><div class="prop-image"><img v-if="prop.reference_asset_id" :src="api.assetFileUrl(prop.reference_asset_id)" :alt="prop.name" /><SvgIcon v-else name="image" :size="28" /><span v-if="jobFor(prop.id)">{{ jobFor(prop.id).progress }}% · {{ jobFor(prop.id).progress_message }}</span></div><div class="prop-fields"><div class="prop-name"><input v-model="prop.name" @change="updateProp(prop)" /><button @click="removeProp(prop)"><SvgIcon name="trash" :size="15" /></button></div><textarea v-model="prop.description" placeholder="外观、材质、尺寸与细节" @change="updateProp(prop)"></textarea><textarea v-model="prop.narrative_significance" placeholder="剧情作用" @change="updateProp(prop)"></textarea><textarea v-model="prop.visual_prompt" placeholder="英文视觉 Prompt（生成时使用）" @change="updateProp(prop)"></textarea><button v-if="jobFor(prop.id)" class="btn danger-outline small" :disabled="busyId === jobFor(prop.id).id" @click="cancelJob(jobFor(prop.id))">{{ busyId === jobFor(prop.id).id ? '正在停止…' : '停止生成' }}</button><button v-else class="btn secondary small" :disabled="busyId === prop.id" @click="generateProp(prop)"><SvgIcon name="image" :size="14" />{{ prop.reference_asset_id ? '按当前风格重新生成' : '生成道具图片' }}</button></div></article></div></section></div>
    <p class="asset-note">参考图用于锁定跨镜头一致性；临时背景无需提前生成。所有新图片自动使用项目风格，排队和生成中的任务都可以在右侧生成队列停止。</p>
  </div>
</template>

<style scoped>
