;font-size:11px}.prop-fields .btn{width:100%;margin-top:8px}.danger-outline{color:#b44343;border-color:#e1bcbc;background:#fff}.danger-outline:hover{background:#fff3f3}@media(max-width:800px){.script-assets-actions,.style-panel{align-items:flex-start;flex-direction:column}.script-assets-actions>div:last-child{flex-wrap:wrap}.style-control{width:100%}.deferred-panel{flex-direction:column}.deferred-list{justify-content:flex-start}}@media(max-width:700px){.assets-toolbar{align-items:flex-start;gap:10px}.segmented button{padding:7px 9px;font-size:11px}}
</style>
